package com.steven.assets.service.srpp.report;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.math.*;
import java.time.*;
import java.time.temporal.*;
import java.util.*;

/** Scalar ports of confirmed-fill cadence and Bull/BearLadder state equations. No IO or state writes. */
public final class SrppReportStateCalculator {
    private static final JsonNodeFactory J=JsonNodeFactory.instance;
    private static final BigDecimal ZERO=BigDecimal.ZERO,ONE=BigDecimal.ONE,EPS=new BigDecimal("0.00000001");
    private static final MathContext MC=MathContext.DECIMAL128;
    private SrppReportStateCalculator(){}

    public static ObjectNode paceAdvance(JsonNode cfg,JsonNode before,LocalDate date,BigDecimal fx,JsonNode fills){
        ObjectNode state=object(before,"GLOBAL_PACE_STATE_UNVERIFIED");
        if(!state.path("verified").asBoolean()||!fills.isArray())throw gap("GLOBAL_PACE_STATE_UNVERIFIED");
        LocalDate last=null;
        Set<String> processed=new HashSet<>();if(!state.path("processedFillIds").isArray())throw gap("PACE_EXACT_FILL_IDS_UNVERIFIED");state.path("processedFillIds").forEach(id->processed.add(id.asText()));for(JsonNode fill:fills){String fillId=fill.path("fillId").asText();if(fillId.isBlank()||!processed.add(fillId))throw gap("PACE_EXACT_FILL_IDS_UNVERIFIED");if(!fill.path("confirmed").asBoolean())throw gap("UNCONFIRMED_FILL_CANNOT_CONSUME_PACE");LocalDate day=LocalDate.parse(fill.path("date").asText());if(day.isAfter(date)||last!=null&&day.isBefore(last))throw gap("PACE_FILL_CHRONOLOGY_UNVERIFIED");last=day;begin(cfg,state,day,number(fill,"fx"));String code=fill.path("symbol").asText();if(!Set.of("VOO","009826").contains(code))throw gap("PACE_FILL_OUTSIDE_UNIVERSE");ObjectNode account=object(state.path(code),"GLOBAL_PACE_STATE_UNVERIFIED");BigDecimal value=number(fill,"nominalTwd"),spent=number(account,"spent");if(value.signum()<0)throw gap("NEGATIVE_CONFIRMED_FILL");put(account,"spent",spent.add(value));if(value.compareTo(EPS)>0){if(code.equals("VOO")){put(account,"lastFillPrice",number(fill,"price"));if(!fill.path("scheduled").asBoolean()){account.put("monthBatches",integer(account,"monthBatches")+1);account.put("weekBatches",integer(account,"weekBatches")+1);put(account,"previousShortfall",number(account,"previousShortfall").subtract(value).max(ZERO));}}else{int lots=number(fill,"shares").divide(new BigDecimal("1000"),0,RoundingMode.HALF_EVEN).intValueExact();if(lots<0)throw gap("NEGATIVE_CONFIRMED_FILL");account.put("dayLots",integer(account,"dayLots")+lots);account.put("weekLots",integer(account,"weekLots")+lots);}}state.set(code,account);}
        begin(cfg,state,date,fx);ArrayNode ids=state.putArray("processedFillIds");processed.stream().sorted().forEach(ids::add);return state;
    }
    private static void begin(JsonNode cfg,ObjectNode state,LocalDate date,BigDecimal fx){
        if(fx.signum()<=0)throw gap("FX_UNVERIFIED");String month=YearMonth.from(date).toString(),previous=state.path("month").asText();boolean changed=!month.equals(previous);
        if(!previous.isEmpty()&&YearMonth.parse(previous).isAfter(YearMonth.from(date)))throw gap("PACE_STATE_FROM_FUTURE");
        if(changed){boolean consecutive=!previous.isEmpty()&&YearMonth.parse(previous).plusMonths(1).equals(YearMonth.from(date));for(String code:List.of("VOO","009826")){ObjectNode account=object(state.path(code),"GLOBAL_PACE_STATE_UNVERIFIED");BigDecimal spent=number(account,"spent"),baseline=number(cfg.path(code),"monthly_baseline_twd").multiply(state.path("halved").asBoolean()?new BigDecimal("0.5"):ONE),shortfall=previous.isEmpty()?ZERO:baseline.subtract(spent).max(ZERO);put(account,"previousShortfall",consecutive?shortfall:ZERO);int count=integer(account,"consecutiveShortfalls");account.put("consecutiveShortfalls",shortfall.compareTo(new BigDecimal("0.01"))>0?consecutive?count+1:1:0);put(account,"spent",ZERO);if(code.equals("VOO"))account.put("monthBatches",0);state.set(code,account);}state.put("month",month);state.put("halved",false);}
        state.put("halved",state.path("halved").asBoolean()||fx.compareTo(number(cfg,"fx_halving_threshold"))>0);
        String week=String.format(Locale.ROOT,"%04d-W%02d",date.get(IsoFields.WEEK_BASED_YEAR),date.get(IsoFields.WEEK_OF_WEEK_BASED_YEAR));if(!week.equals(state.path("week").asText())){state.put("week",week);((ObjectNode)state.path("VOO")).put("weekBatches",0);((ObjectNode)state.path("009826")).put("weekLots",0);}if(!date.toString().equals(state.path("day").asText())){state.put("day",date.toString());((ObjectNode)state.path("009826")).put("dayLots",0);}
    }

    /** The caller supplies actual completed-session indices and verified window evidence, never a monthly proxy. */
    public static ObjectNode ladderAdvance(JsonNode policy,String mode,JsonNode before,JsonNode event,int cooldown){
        if(!Set.of("BULL","BEAR").contains(mode)||cooldown<1)throw gap("LADDER_SCOPE_INVALID");ObjectNode state=object(before,"LADDER_STATE_UNVERIFIED");JsonNode rungs=policy.path(mode.equals("BULL")?"bull_ladder_d156":"bear_ladder_d141");validateRungs(rungs,mode);if(!state.path("verified").asBoolean()||!event.path("verified").asBoolean()||!event.path("qualified").isBoolean()||!state.path("active").isBoolean())throw gap("LADDER_STATE_UNVERIFIED");int count=rungs.size();validateStateArrays(state,count);int session=integer(event,"session"),last=integerAllowNegative(state,"lastFill");BigDecimal total=number(event,"total"),equity=number(event,"equity");if(total.signum()<=0||equity.signum()<0)throw gap("LADDER_VALUATION_UNVERIFIED");boolean qualified=event.path("qualified").asBoolean();
        if(mode.equals("BEAR")){BigDecimal dd=number(event,"drawdown");if(dd.compareTo(new BigDecimal("-0.10"))>0){BigDecimal initial=number(state,"initialBonds");reset(state,count);put(state,"initialBonds",initial);}BigDecimal eligible=number(event,"eligibleBonds"),bonds=number(event,"totalBonds"),cash=number(event,"availableCash"),bondLimit=eligible.max(ZERO).multiply(number(policy,"bear_bond_sale_max_share")).min(bonds.subtract(total.multiply(number(policy,"total_bond_floor"))).max(ZERO));BigDecimal planned=cash.max(ZERO).add(bondLimit).min(total.multiply(number(policy,"bear_equity_cap")).subtract(equity).max(ZERO));if(!state.path("active").asBoolean()&&qualified&&dd.compareTo(number(rungs.get(0),"drawdown").negate())<=0&&planned.compareTo(new BigDecimal("0.01"))>0){arm(state,rungs,planned);put(state,"initialBonds",eligible);put(state,"bondsSold",ZERO);}put(state,"drawdown",dd);
        }else{BigDecimal gain=number(event,"gain"),planned=equity.subtract(total.multiply(number(policy,"monthly_bull_first_equity_target"))).max(ZERO);if(!state.path("active").asBoolean()&&qualified&&gain.compareTo(number(rungs.get(0),"gain_above_anchor"))>=0&&planned.compareTo(new BigDecimal("0.01"))>0){arm(state,rungs,planned);put(state,"highWaterGain",gain);}if(state.path("active").asBoolean())put(state,"highWaterGain",number(state,"highWaterGain").max(gain));put(state,"gain",gain);BigDecimal high=number(state,"highWaterGain");put(state,"pullback",state.path("active").asBoolean()&&high.compareTo(ONE.negate())>0?high.subtract(gain).divide(ONE.add(high),MC):ZERO);state.put("pendingClose",state.path("active").asBoolean()&&event.path("corrected").asBoolean());}
        JsonNode fills=event.path("fills");if(!fills.isArray())throw gap("LADDER_CONFIRMED_FILLS_UNVERIFIED");for(JsonNode fill:fills){if(integer(fill,"session")>session)throw gap("LADDER_FILL_FROM_FUTURE");record(state,fill,mode,count);}
        int completed=completed(state),rung=Math.min(completed,count-1);JsonNode rule=rungs.get(rung);boolean allowed=state.path("active").asBoolean()&&qualified&&completed<count&&session-integerAllowNegative(state,"lastFill")>=cooldown;
        if(mode.equals("BULL"))allowed&=number(state,"highWaterGain").compareTo(number(rule,"gain_above_anchor"))>=0&&number(state,"pullback").compareTo(number(rule,"pullback_from_high_watermark"))>=0&&number(state,"gain").signum()>0;else allowed&=number(state,"drawdown").compareTo(number(rule,"drawdown").negate())<=0;
        ObjectNode out=J.objectNode();out.put("nextBatch",rung);put(out,"ladderAmount",allowed?number(state.path("budget").get(rung)):ZERO);out.put("eligible",allowed);out.put("growingFill",number(out,"ladderAmount").compareTo(number(state,"lastAmount").add(EPS))>0);if(mode.equals("BEAR"))put(out,"bondAllowance",number(state,"initialBonds").multiply(number(policy,"bear_bond_sale_max_share")).subtract(number(state,"bondsSold")).max(ZERO));else{put(out,"gainAboveAnchor",number(state,"highWaterGain"));put(out,"pullback",number(state,"pullback"));}if(mode.equals("BULL")&&state.path("pendingClose").asBoolean())reset(state,count);out.set("stateAfter",state);return out;
    }
    private static void validateRungs(JsonNode rungs,String mode){if(!rungs.isArray()||rungs.size()<4||rungs.size()>5)throw gap("LADDER_POLICY_INVALID");BigDecimal weight=ZERO,total=ZERO,threshold=null,pull=null;for(JsonNode r:rungs){BigDecimal w=number(r,"share_of_window_budget"),t=number(r,mode.equals("BULL")?"gain_above_anchor":"drawdown");if(w.compareTo(weight)<=0||threshold!=null&&t.compareTo(threshold)<=0||weight.signum()==0&&w.compareTo(new BigDecimal("0.10"))>0)throw gap("LADDER_POLICY_INVALID");if(mode.equals("BULL")){BigDecimal p=number(r,"pullback_from_high_watermark");if(pull!=null&&p.compareTo(pull)<=0||p.compareTo(new BigDecimal("0.10"))>=0)throw gap("LADDER_POLICY_INVALID");pull=p;}weight=w;threshold=t;total=total.add(w);}if(total.subtract(ONE).abs().compareTo(new BigDecimal("0.00000001"))>0)throw gap("LADDER_POLICY_INVALID");}
    private static void validateStateArrays(ObjectNode s,int n){for(String key:List.of("budget","spent","fills")){if(!s.path(key).isArray()||s.path(key).size()!=n)throw gap("LADDER_STATE_UNVERIFIED");for(JsonNode v:s.path(key))if(number(v).signum()<0)throw gap("LADDER_STATE_UNVERIFIED");}integerAllowNegative(s,"lastFill");number(s,"lastAmount");number(s,"windowBudget");}
    private static void arm(ObjectNode s,JsonNode rungs,BigDecimal budget){s.put("active",true);put(s,"windowBudget",budget);ArrayNode b=s.putArray("budget");rungs.forEach(r->b.add(decimal(budget.multiply(number(r,"share_of_window_budget")))));}
    private static void reset(ObjectNode s,int count){s.put("active",false);put(s,"windowBudget",ZERO);for(String key:List.of("budget","spent","fills")){ArrayNode a=s.putArray(key);for(int i=0;i<count;i++)a.add("0");}s.put("lastFill",-100);put(s,"lastAmount",ZERO);put(s,"initialBonds",ZERO);put(s,"bondsSold",ZERO);put(s,"highWaterGain",ZERO);put(s,"pullback",ZERO);s.put("pendingClose",false);}
    private static int completed(JsonNode s){int count=0;for(JsonNode fill:s.path("fills"))if(number(fill).signum()>0)count++;return count;}
    private static void record(ObjectNode s,JsonNode fill,String mode,int count){if(!fill.path("confirmed").asBoolean())throw gap("UNCONFIRMED_FILL_CANNOT_CONSUME_LADDER");BigDecimal value=number(fill,"deployed");if(value.signum()<0)throw gap("NEGATIVE_CONFIRMED_FILL");if(value.compareTo(EPS)<=0)return;int rung=integer(fill,"rung"),session=integer(fill,"session"),next=completed(s);if(next>=count||rung!=next||value.compareTo(number(s.path("budget").get(rung)).add(new BigDecimal("0.000001")))>0||value.compareTo(number(s,"lastAmount").add(EPS))<=0||session<integerAllowNegative(s,"lastFill"))throw gap("LADDER_BATCH_SEQUENCE_SIZE_OR_BUDGET_VIOLATED");((ArrayNode)s.path("spent")).set(rung,TextNode.valueOf(decimal(number(s.path("spent").get(rung)).add(value))));((ArrayNode)s.path("fills")).set(rung,TextNode.valueOf(decimal(number(s.path("fills").get(rung)).add(ONE))));s.put("lastFill",session);put(s,"lastAmount",value);if(mode.equals("BEAR"))put(s,"bondsSold",number(s,"bondsSold").add(number(fill,"bondSale")));}

    public static ObjectNode reserveAdvance(JsonNode before,JsonNode completedSessions,JsonNode fills,LocalDate date,JsonNode config){ObjectNode state=object(before,"ROTATION_RESERVE_STATE_UNVERIFIED");if(!state.path("verified").asBoolean()||!state.path("lots").isArray()||!completedSessions.isArray()||!fills.isArray())throw gap("ROTATION_RESERVE_STATE_UNVERIFIED");Map<String,Boolean>days=new TreeMap<>();for(JsonNode session:completedSessions){String day=session.path("date").asText();LocalDate d=LocalDate.parse(day);if(!d.isBefore(date)||!session.path("bearPaused").isBoolean()||days.put(day,session.path("bearPaused").asBoolean())!=null)throw gap("RESERVE_SESSION_CALENDAR_UNVERIFIED");}LocalDate last=LocalDate.parse(state.path("lastProcessedDate").asText());if(last.isAfter(date))throw gap("RESERVE_STATE_FROM_FUTURE");ArrayNode lots=state.path("lots").deepCopy();BigDecimal total=ZERO,overdue=ZERO;for(JsonNode n:lots){ObjectNode lot=(ObjectNode)n;LocalDate settled=LocalDate.parse(lot.path("settledDate").asText());if(settled.isAfter(date)||!lot.path("settlementVerified").asBoolean())throw gap("RESERVE_UNSETTLED_SOURCE");int age=integer(lot,"age");for(var entry:days.entrySet())if(LocalDate.parse(entry.getKey()).isAfter(settled)&&LocalDate.parse(entry.getKey()).isAfter(last)&&!entry.getValue())age++;lot.put("age",age);BigDecimal amount=number(lot,"amount");if(amount.signum()<0)throw gap("RESERVE_AMOUNT_INVALID");total=total.add(amount);}
        for(JsonNode fill:fills){if(!fill.path("confirmed").asBoolean()||!"VOO".equals(fill.path("symbol").asText())||!"美股".equals(fill.path("market").asText()))throw gap("RESERVE_FILL_IDENTITY_UNVERIFIED");BigDecimal remaining=number(fill,"payment");if(remaining.signum()<0||remaining.compareTo(total)>0)throw gap("RESERVE_PAYMENT_EXCEEDS_SETTLED_AMOUNT");for(JsonNode n:lots){ObjectNode lot=(ObjectNode)n;BigDecimal take=number(lot,"amount").min(remaining);put(lot,"amount",number(lot,"amount").subtract(take));remaining=remaining.subtract(take);if(remaining.signum()==0)break;}total=total.subtract(number(fill,"payment"));}
        if(!fills.isEmpty()){ArrayNode retained=J.arrayNode();for(JsonNode lot:lots)if(number(lot,"amount").compareTo(EPS)>0)retained.add(lot);lots=retained;}for(JsonNode lot:lots)if(integer(lot,"age")>integer(config,"stock_rotation_reserve_max_idle_sessions"))overdue=overdue.add(number(lot,"amount"));state.set("lots",lots);if(!days.isEmpty())state.put("lastProcessedDate",days.keySet().stream().max(String::compareTo).orElseThrow());ObjectNode out=J.objectNode();put(out,"settledReserve",total);put(out,"overdueReserve",overdue);out.set("stateAfter",state);return out;}

    /** Original TransitionLedger overdue reserve principal: batch timing is bypassed, amount caps and exact buy gates remain. */
    public static BigDecimal reserveDeployment(BigDecimal overdue,BigDecimal physical,BigDecimal individualRoom,BigDecimal groupRoom,BigDecimal equityRoom,BigDecimal monthlyRoom,BigDecimal priceLevel,BigDecimal commission,boolean bearPaused,boolean exactBuyGates){for(BigDecimal value:List.of(overdue,physical,individualRoom,groupRoom,equityRoom,monthlyRoom,commission))if(value.signum()<0)throw gap("RESERVE_DEPLOYMENT_SOURCE_INVALID");if(priceLevel.signum()<=0)throw gap("RESERVE_PRICE_LEVEL_UNVERIFIED");if(bearPaused||!exactBuyGates)return ZERO;return overdue.min(physical).divide(ONE.add(commission),MC).min(individualRoom).min(groupRoom).min(equityRoom).min(monthlyRoom.divide(priceLevel,MC));}
    private static ObjectNode object(JsonNode n,String reason){if(!(n instanceof ObjectNode))throw gap(reason);return n.deepCopy();}
    private static BigDecimal number(JsonNode parent,String key){return number(parent.get(key));}
    private static BigDecimal number(JsonNode n){if(n==null||n.isNull()||!n.isNumber()&&!n.isTextual())throw gap("STATE_NUMERIC_SOURCE_UNVERIFIED");try{return new BigDecimal(n.asText());}catch(NumberFormatException invalid){throw gap("STATE_NUMERIC_SOURCE_UNVERIFIED");}}
    private static int integer(JsonNode n,String key){int value=integerAllowNegative(n,key);if(value<0)throw gap("STATE_COUNT_NEGATIVE");return value;}
    private static int integerAllowNegative(JsonNode n,String key){try{return number(n,key).intValueExact();}catch(ArithmeticException invalid){throw gap("STATE_COUNT_UNVERIFIED");}}
    private static void put(ObjectNode n,String key,BigDecimal value){n.put(key,decimal(value));}
    private static String decimal(BigDecimal value){return value.signum()==0?"0":value.stripTrailingZeros().toPlainString();}
    private static IllegalArgumentException gap(String reason){return new IllegalArgumentException(reason);}
}
